(()=>{'use strict';const s=document.querySelector('.result-scenes'),stage=s.querySelector('.result-stage'),cards=[...s.querySelectorAll('[data-result-card]')],copies=[...s.querySelectorAll('[data-result-copy]')],tabs=[...s.querySelectorAll('[data-result-step]')],reduced=matchMedia('(prefers-reduced-motion:reduce)'),heading=s.querySelector('.result-copy h2');let frame=0,previous=-1;
// Each page owns its image, narrative and App outcome, so all layers turn together.
cards.forEach((c,i)=>{const copy=document.createElement('div');copy.className='result-copy page-copy';copy.append(heading.cloneNode(true),copies[i]);c.append(copy);copies[i].classList.add('active');copies[i].removeAttribute('aria-hidden')});s.querySelector('.result-stage>.result-copy').remove();
function render(){frame=0;const r=s.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/Math.max(1,s.offsetHeight-stage.offsetHeight))),x=p*3.6,n=Math.min(3,Math.floor(x+.12));cards.forEach((c,i)=>{const enter=i===0?1:Math.max(0,Math.min(1,(x-i+.6)/.6)),exit=Math.max(0,Math.min(1,(x-i-.4)/.6));c.style.zIndex=i+1;c.style.opacity=reduced.matches?(i===n?1:0):1;c.style.transform=reduced.matches?'none':`translateY(${(1-enter)*105}%) scale(${1-exit*.055})`;c.style.filter=`brightness(${1-exit*.35})`;c.style.borderRadius=(exit*22)+'px';c.classList.add('active');c.inert=i!==n;c.setAttribute('aria-hidden',String(i!==n));});if(n!==previous){previous=n;tabs.forEach((t,i)=>t.setAttribute('aria-current',i===n?'step':'false'));}}function queue(){if(!frame)frame=requestAnimationFrame(render)}tabs.forEach((b,i)=>b.onclick=()=>scrollTo({top:s.getBoundingClientRect().top+scrollY+(i/3.6)*(s.offsetHeight-stage.offsetHeight),behavior:reduced.matches?'instant':'smooth'}));addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);s.querySelectorAll('[data-save-result]').forEach(b=>b.onclick=()=>{b.hidden=true;b.nextElementSibling.hidden=false});render()})();
